:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --text: #e0e0f0;
  --accent: #4caf50;
  --danger: #e74c3c;
  --muted: #8888aa;
  --radius: 12px;
  --gap: 1.5rem;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.card {
  background: var(--card);
  border-radius: var(--radius);
  padding: 2rem;
  width: 100%;
  max-width: 480px;
  text-align: center;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: var(--gap);
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.subtitle {
  color: var(--muted);
  font-size: 1rem;
}

.stats {
  display: flex;
  justify-content: center;
  gap: 2rem;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.stat-label {
  font-size: 0.875rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.box {
  background: var(--muted);
  border-radius: var(--radius);
  min-height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  user-select: none;
  padding: 1rem;
  outline: none;
}

.box:hover {
  filter: brightness(1.1);
}

.box:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.box:active {
  transform: scale(0.98);
}

.box.ready {
  background: var(--accent);
}

.box.early {
  background: var(--danger);
}

.box-message {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--text);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
}

.btn {
  font-family: inherit;
  font-size: 1.125rem;
  font-weight: 600;
  padding: 0.875rem 2rem;
  border: none;
  border-radius: var(--radius);
  background: var(--accent);
  color: var(--text);
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

.btn:hover {
  background: #5bc45f;
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 3px;
}

.btn:active {
  transform: scale(0.97);
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

@media (max-width: 400px) {
  .card {
    padding: 1.25rem;
  }
  h1 {
    font-size: 1.5rem;
  }
  .box {
    min-height: 120px;
  }
}

(function () {
  'use strict';

  const box = document.getElementById('box');
  const message = document.getElementById('message');
  const startBtn = document.getElementById('start-btn');
  const lastTimeEl = document.getElementById('last-time');
  const bestTimeEl = document.getElementById('best-time');

  let state = 'idle'; // idle | waiting | ready | result | early
  let timeoutId = null;
  let startTime = 0;
  let bestTime = null;

  // Load best time from localStorage if available
  try {
    const stored = localStorage.getItem('reactionBestTime');
    if (stored !== null) {
      bestTime = parseInt(stored, 10);
      if (!isNaN(bestTime)) bestTimeEl.textContent = bestTime + ' ms';
    }
  } catch (e) {
    // localStorage unavailable, ignore
  }

  function setState(newState) {
    state = newState;
    box.classList.remove('ready', 'early');
    if (state === 'ready') box.classList.add('ready');
    if (state === 'early') box.classList.add('early');
  }

  function resetBox() {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
    setState('idle');
    message.textContent = 'Press Start';
    startBtn.disabled = false;
  }

  function startGame() {
    if (state === 'waiting' || state === 'ready') return;
    resetBox();
    setState('waiting');
    message.textContent = 'Wait for green...';
    startBtn.disabled = true;

    const delay = 1000 + Math.random() * 4000; // 1–5 seconds
    timeoutId = setTimeout(function () {
      timeoutId = null;
      setState('ready');
      message.textContent = 'Click!';
      startTime = performance.now();
    }, delay);
  }

  function handleBoxClick() {
    if (state === 'waiting') {
      // Clicked too early
      if (timeoutId) {
        clearTimeout(timeoutId);
        timeoutId = null;
      }
      setState('early');
      message.textContent = 'Too soon!';
      startBtn.disabled = false;
      return;
    }

    if (state === 'ready') {
      const reaction = Math.round(performance.now() - startTime);
      setState('result');
      message.textContent = reaction + ' ms';
      lastTimeEl.textContent = reaction + ' ms';

      if (bestTime === null || reaction < bestTime) {
        bestTime = reaction;
        bestTimeEl.textContent = bestTime + ' ms';
        try {
          localStorage.setItem('reactionBestTime', bestTime);
        } catch (e) {
          // ignore
        }
      }

      startBtn.disabled = false;
      return;
    }

    if (state === 'idle' || state === 'result' || state === 'early') {
      // Clicking the box when not in a round does nothing (or could restart)
      // We'll just ignore to avoid accidental restarts.
    }
  }

  startBtn.addEventListener('click', startGame);

  box.addEventListener('click', handleBoxClick);

  box.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      handleBoxClick();
    }
  });

  // Initialize
  resetBox();
})();
